// procedural world sketch for: Synthetic Sensor Environment Generator
let s = 63901934;
const rnd = () => (s = (s * 1664525 + 1013904223) >>> 0) / 4294967296;
const W = 17, H = 11; let land = 0, water = 0;
for (let y = 0; y < H; y++) for (let x = 0; x < W; x++) { if (rnd() < 0.48) land++; else water++; }
console.log(JSON.stringify({ width: W, height: H, landCells: land, waterCells: water,
  landFraction: +(land / (W * H)).toFixed(3), seed: 63901934 }));

